"""Evaluation helpers -- R9/R10: metrics consume scores first, labels second.

Labels are touched only here, after anomaly scores exist.
"""
from __future__ import annotations

import numpy as np
from sklearn.metrics import (
    average_precision_score,
    precision_recall_curve,
    roc_auc_score,
)


def roc_auc(scores, labels) -> float:
    """R9: AUC-ROC via sklearn (ties handled by rank averaging)."""
    return float(roc_auc_score(np.asarray(labels).ravel(), np.asarray(scores).ravel()))


def auc_pr(scores, labels) -> float:
    """R9: AUC-PR as average precision (ADBench/sklearn convention)."""
    return float(average_precision_score(np.asarray(labels).ravel(), np.asarray(scores).ravel()))


def auc_pr_trapezoid(scores, labels) -> float:
    """Secondary AUC-PR reading: trapezoidal area under the PR curve."""
    prec, rec, _ = precision_recall_curve(np.asarray(labels).ravel(), np.asarray(scores).ravel())
    return float(np.trapz(prec[::-1], rec[::-1]))


def summarize(values) -> dict:
    v = np.asarray(list(values), dtype=np.float64)
    return {
        "mean": float(v.mean()),
        "std": float(v.std(ddof=0)),
        "std_sample": float(v.std(ddof=1)) if v.size > 1 else 0.0,
        "min": float(v.min()),
        "max": float(v.max()),
        "n": int(v.size),
        "values": [float(x) for x in v],
    }

